## Document Cancel

**Endpoint:** POST /webhook/document-cancel

**Purpose:** Cancel a running job and return credits summary

**Request:**
```json
{
  "job_id": "uuid",
  "user_id": "discord_user_id",
  "reason": "user_requested"
}
```

**Response:**
```json
{
  "success": true,
  "job_id": "uuid",
  "previous_status": "processing",
  "new_status": "cancelled",
  "credits": {
    "consumed": { "total_tokens": 7500, "cost_usd": 0.015 },
    "saved": { "total_tokens": 15000, "cost_usd": 0.030 }
  }
}
```

**Error:**
```json
{
  "error": {
    "code": 400,
    "message": "Cannot cancel completed job",
    "status": "INVALID_STATE_TRANSITION"
  }
}
```

**State transitions:**
- pending → cancelled ✅
- processing → cancelled ✅
- completed/failed → ❌ (400)

**API:** PATCH /api/v2/jobs/{job_id}

**RFC:** RFC-017

parameters.jsCode:
// Validate input - return error object instead of throwing
const input = $input.first().json;
const body = input.body || input;

if (!body.job_id) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: 'job_id is required',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    jobId: body.job_id,
    userId: body.user_id || null,
    reason: body.reason || 'user_requested'
  }
}];

// Check if job can be cancelled per API state machine
const input = $input.first().json;
const prevData = $('Input Valid?').first().json;

const statusCode = input.statusCode || 200;
const job = input.body || input;

// Handle job not found (404)
if (statusCode === 404) {
  return [{
    json: {
      ...prevData,
      canCancel: false,
      error: {
        code: 404,
        message: `Job ${prevData.jobId} not found`,
        status: 'NOT_FOUND'
      }
    }
  }];
}

// Check status - only pending and processing can be cancelled
const status = job.status || 'unknown';
const canCancel = ['pending', 'processing'].includes(status);

if (!canCancel) {
  return [{
    json: {
      ...prevData,
      canCancel: false,
      error: {
        code: 400,
        message: `Cannot transition from '${status}' to 'cancelled'`,
        status: 'INVALID_STATE_TRANSITION',
        current_status: status,
        allowed_transitions: status === 'pending' ? ['processing', 'cancelled'] : []
      }
    }
  }];
}

// Extract credits and progress info from job
const progress = job.progress || { current: 0, total: 0, percentage: 0 };
const credits = job.credits || {};
const creditsConsumed = credits.consumed || { total_tokens: 0, cost_usd: 0 };
const creditsEstimated = credits.estimated_total || creditsConsumed;

return [{
  json: {
    ...prevData,
    canCancel: true,
    job: job,
    previousStatus: status,
    progress: progress,
    creditsConsumed: creditsConsumed,
    creditsEstimated: creditsEstimated
  }
}];

// Build success response with credits summary per API spec
const patchResult = $input.first().json;
const prevData = $('Can Cancel?').first().json;

const patchStatusCode = patchResult.statusCode || 200;
const patchBody = patchResult.body || patchResult;

// Handle PATCH errors (e.g., race condition where status changed)
if (patchStatusCode >= 400) {
  if (patchBody.detail?.code === 'INVALID_STATE_TRANSITION') {
    return [{
      json: {
        error: {
          code: 400,
          message: patchBody.detail.message,
          status: 'INVALID_STATE_TRANSITION',
          current_status: patchBody.detail.current_status
        }
      }
    }];
  }
  return [{
    json: {
      error: {
        code: patchStatusCode,
        message: patchBody.detail || 'Failed to cancel job',
        status: 'API_ERROR'
      }
    }
  }];
}

// Calculate saved credits
const consumed = prevData.creditsConsumed || { total_tokens: 0, cost_usd: 0 };
const estimated = prevData.creditsEstimated || consumed;
const saved = {
  total_tokens: Math.max(0, (estimated.total_tokens || 0) - (consumed.total_tokens || 0)),
  cost_usd: Math.max(0, (estimated.cost_usd || 0) - (consumed.cost_usd || 0))
};

const progress = prevData.progress || { current: 0, total: 0 };

return [{
  json: {
    success: true,
    job_id: prevData.jobId,
    previous_status: prevData.previousStatus,
    new_status: 'cancelled',
    cancelled_at: patchBody.cancelled_at || new Date().toISOString(),
    progress: {
      current: progress.current || 0,
      total: progress.total || 0,
      percentage: progress.percentage || 0
    },
    credits: {
      consumed: {
        total_tokens: consumed.total_tokens || 0,
        cost_usd: consumed.cost_usd || 0
      },
      saved: {
        total_tokens: saved.total_tokens,
        cost_usd: saved.cost_usd
      }
    },
    message: `Job annulé. ${progress.current || 0}/${progress.total || '?'} traités. ${(consumed.cost_usd || 0).toFixed(3)}$ consommés, ${saved.cost_usd.toFixed(3)}$ économisés.`
  }
}];

